}).on('close', () => {
  // 入力を解析
  const iteration = parseInt(inputs[0], 10);
  const total = parseInt(inputs[1], 10);
  const prefix = inputs[2] || '';
  const suffix = inputs[3] || '';
  const decimals = parseInt(inputs[4], 10) || 0;
  const length = parseInt(inputs[5], 10) || 100;
  const fill = inputs[6] || '=';
  const printEnd = inputs[7] || '\r\n';

  // 進捗を計算
  const percent = (iteration / total) * 100;
  const filledLength = Math.min(Math.round(length * iteration / total), length);
  const bar = fill.repeat(filledLength) + '-'.repeat(length - filledLength);

  // 進捗バーを出力
  console.log(`${prefix} [${bar}] ${percent.toFixed(decimals)}% ${suffix}${printEnd}`);
});
