```javascript
function progress(iteration, total, prefix = '', suffix = '', decimals = 1, length = 100, fill = '█', printEnd = '\r') {
    const percent = Math.round((iteration / total) * 100 * 10 ** decimals) / 10 ** decimals;
    const filledLength = Math.round(length * iteration / total);
    const bar = fill.repeat(filledLength) + '-'.repeat(length - filledLength);
    process.stdout.write(`${prefix} [${bar}] ${percent}% ${suffix}${printEnd}`);
    if (iteration === total) {
        console.log();
    }
}

const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
});

let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line);
    if (inputLines.length === 4) {
        const iteration = parseInt(inputLines[0], 10);
        const total = parseInt(inputLines[1], 10);
        const prefix = inputLines[2];
        const suffix = inputLines[3];
        for (let i = 1; i <= total; i++) {
            progress(i, total, prefix, suffix);
            process.stdout.write('\x1b[1A'); // Move cursor up to overwrite the line
        }
        rl.close();
    }
});
```

