// ラッパーをシミュレートするためのクラス
class DataParallel {
    constructor(module) {
        this.module = module;
    }
}

class DistributedDataParallel {
    constructor(module) {
        this.module = module;
    }
}

class DeepSpeed {
    constructor(module) {
        this.module = module;
    }
}

class FSDP {
    constructor(module) {
        this.module = module;
    }
}

function unwrapModel(model) {
    if (model instanceof DataParallel) {
        return model.module;
    } else if (model instanceof DistributedDataParallel) {
        return model.module;
    } else if (model instanceof DeepSpeed) {
        return model.module;
    } else if (model instanceof FSDP) {
        return model.module;
    }
    return model;
}

// 標準入力から読み取るためのシミュレーションコード
const readline = require('readline');
