```javascript
const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

function _validate_time_format(time) {
    const timeRegex = /^(\d+):(\d+):(\d+)$/;
    const match = time.match(timeRegex);
    if (match) {
        return `${match[1]}:${match[2]}:${match[3]}`;
    } else {
        throw new Error('Invalid time format. Expected format: HH:MM:SS');
    }
}

function _get_alloc_cmd(nodes, time, account, options) {
    let salloc_args = ['--no-shell', '-N', String(nodes), '-J', 'SmartSim'];
    if (time) {
        salloc_args.push('-t', _validate_time_format(time));
    }
    if (account) {
        salloc_args.push('-A', String(account));
    }
    if (options) {
        for (const [key, value] of Object.entries(options)) {
            const prefix = key.length === 1 ? '-' : '--';
            if (!value) {
                salloc_args.push(prefix + key);
            } else {
                salloc_args.push(`${prefix}${key}=${value}`);
            }
        }
    }
    return salloc_args;
}

function main() {
    rl.on('line', (line) => {
        const input = JSON.parse(line);
        const { nodes, time, account, options } = input;
        try {
            const command = _get_alloc_cmd(nodes, time, account, options);
            console.log(command);
            process.exit(0);
        } catch (error) {
            console.error(error.message);
            process.exit(1);
        }
    });
}

main();
```

