async function main() {
  try {
    // 標準入力から必要な値を読み取る
    const file_id = await question('Google Drive file ID: ');
    const output_path = await question('Local path to save file: ');
    const credentials_path = await question('Path to OAuth2 credentials: ');

    // 認証をセットアップ
    const auth = new google.auth.OAuth2();
    const authClient = await auth.fromFile(credentials_path);

    // アクセストークンをキャッシュファイルから読み取る
    let tokens;
    try {
      tokens = JSON.parse(fs.readFileSync(path.join(__dirname, 'token.json')));
    } catch (e) {
      // キャッシュされたトークンが存在しない場合,認証を行う
      const authUrl = authClient.generateAuthUrl({
        access_type: 'offline',
        scope: ['https://www.googleapis.com/auth/drive.readonly']
      });
      console.log('Authorize this app by visiting this url:', authUrl);
      const code = await question('Enter the code from that page here: ');
      const token = await authClient.getToken(code);
      tokens = token.tokens;
      fs.writeFileSync(path.join(__dirname, 'token.json'), JSON.stringify(tokens));
    }
    authClient.setCredentials(tokens);

    // ファイルのアクセスを検証
