      return;
    }

    // ダウンロード前にディスクエスをチェック
    const outputDir = path.dirname(output_path);
    const stat = fs.statSync(outputDir);
    const freeSpace = stat.size ? stat.size - stat.blocks * 512 : stat.size;
    if (freeSpace < 10 * 1024 * 1024) { // 10MBの最低クエス
      console.error('Not enough disk space.');
      return;
    }

    // ファイルをダウンロード
    const dest = fs.createWriteStream(output_path);
    await new Promise((resolve, reject) => {
      const req = drive.files.get({ fileId: file_id, alt: 'media' });
      req.on('response', (res) => {
        res.on('data', (chunk) => {
          dest.write(chunk);
        });
        res.on('end', () => {
          dest.end();
          console.log('File downloaded successfully.');
          resolve();
        });
        res.on('error', (err) => {
