この問題を効率的に解決するためには、特に大規模なデータセットを扱う際に、不要な計算やメモリ使用を避けることが重要です。以下の実装方針に従います：

1. **条件チェックの最適化**: `training`フラグが`False`または`num_dn`が`0`以下の場合、すぐに結果を返すことで、不要な計算を避けます。
2. **メモリ効率の向上**: テンソルの繰り返しやインデックス操作を最小限に抑え、必要なデータのみを作成します。
3. **ベクトル化**: ループを避け、可能な限りベクトル化された操作を使用して計算を高速化します。
4. **条件に基づく計算**: ノイズの追加やインデックスの計算は、条件に基づいてのみ行います。

以下に、これらの方針に基づいたJavaScriptの実装を示します：

```javascript
function get_cdn_group(batch, num_classes, num_queries, class_embed, num_dn = 100, cls_noise_ratio = 0.5, box_noise_scale = 1.0, training = false) {
    if (!training || num_dn <= 0) {
        return [null, null, null, null];
    }

    const gt_groups = batch['gt_groups'];
    const total_num = gt_groups.reduce((a, b) => a + b, 0);
    const max_nums = Math.max(...gt_groups);

    if (max_nums === 0) {
        return [null, null, null, null];
    }

    let num_group = Math.floor(num_dn / max_nums);
    num_group = Math.max(1, num_group);
    const bs = gt_groups.length;
    const gt_cls = batch['gt_cls'];
    const gt_bbox = batch['gt_bboxes'];
    const b_idx = batch['batch_idx'];

    const dn_cls = gt_cls.flatMap(x => [x, x]);
    const dn_bbox = gt_bbox.flatMap(x => [x, x]);
    const dn_b_idx = b_idx.flatMap(x => [x, x]);

    const neg_idx = Array.from({ length: total_num * num_group }, (_, i) => i + num_group * total_num);

    if (cls_noise_ratio > 0) {
        for (let i = 0; i < dn_cls.length; i++) {
            if (Math.random() < cls_noise_ratio * 0.5) {
                dn_cls[i] = Math.floor(Math.random() * num_classes);
            }
        }
    }

    if (box_noise_scale > 0) {
        const known_bbox = gt_bbox.map(bbox => {
            const [x, y, w, h] = bbox;
            return [x, y, x + w, y + h];
        });

        for (let i = 0; i < dn_bbox.length; i++) {
            const [x1, y1, x2, y2] = known_bbox[i];
            const diff = [(x2 - x1) * 0.5, (y2 - y1) * 0.5];
            const rand_sign = Math.random() < 0.5 ? -1 : 1;
            const rand_part = Math.random();
            rand_part += neg_idx.includes(i) ? 1.0 : 0.0;
            const dx = rand_part * rand_sign * diff[0] * box_noise_scale;
            const dy = rand_part * rand_sign * diff[1] * box_noise_scale;
            const newX1 = Math.max(0, Math.min(1, x1 + dx));
            const newY1 = Math.max(0, Math.min(1, y1 + dy));
            const newX2 = Math.max(0, Math.min(1, x2 + dx));
            const newY2 = Math.max(0, Math.min(1, y2 + dy));
            dn_bbox[i] = [newX1, newY1, newX2 - newX1, newY2 - newY1];
        }
    }

    const num_dn = max_nums * 2 * num_group;
    const padding_cls = Array.from({ length: bs }, () => Array(num_dn).fill(0));
    const padding_bbox = Array.from({ length: bs }, () => Array(num_dn).fill([0, 0, 0, 0]));

    const map_indices = gt_groups.flatMap((num, idx) => Array.from({ length: num }, (_, i) => i + idx * max_nums));
    const pos_idx = Array.from({ length: num_group }, (_, i) => map_indices.map(idx => idx + max_nums * i));

    map_indices.forEach((idx, i) => {
        const b_idx_val = b_idx[idx];
        const map_idx = idx + max_nums * i;
        padding_cls[b_idx_val][map_idx] = class_embed[dn_cls[map_idx]];
        padding_bbox[b_idx_val][map_idx] = dn_bbox[map_idx];
    });

    const tgt_size = num_dn + num_queries;
    const attn_mask = Array.from({ length: tgt_size }, () => Array(tgt_size).fill(false));

    for (let i = 0; i < num_group; i++) {
        const start = max_nums * 2 * i;
        const end = max_nums * 2 * (i + 1);
        if (i === 0) {
            for (let j = end; j < num_dn; j++) {
                for (let k = start; k < end; k++) {
                    attn_mask[j][k] = true;
                }
            }
        }
        if (i === num_group - 1) {
            for (let j = start; j < end; j++) {
                for (let k = 0; k < start; k++) {
                    attn_mask[j][k] = true;
                }
            }
        } else {
            for (let j = start; j < end; j++) {
                for (let k = end; k < num_dn; k++) {
                    attn_mask[j][k] = true;
                }
                for (let k = 0; k < start; k++) {
                    attn_mask[j][k] = true;
                }
            }
        }
    }

    const dn_meta = {
        dn_pos_idx: pos_idx.map(p => p.slice()),
        dn_num_group: num_group,
        dn_num_split: [num_dn, num_queries]
    };

    return [padding_cls, padding_bbox, attn_mask, dn_meta];
}
