function isEscaped(array: any[], string: string, index: number): boolean {
    // 数値配列を文字列に変換
    const str = array.join('');
    let backslashCount = 0;

    // インデックスまでバックスラッシュを数える
    for (let i = index; i >= 0; i--) {
        if (str[i] === '\\') {
            backslashCount++;
        } else {
            break;
        }
    }

    // バックスラッシュの数が偶数かどうかを確認
    return backslashCount % 2 === 1;
}
