    /some_text/,
    undefined,
    undefined,
    undefined,
    [[1, 1]],
    [[2, 2]]
);

rl.on('line', (input: string) => {
    const viewDict: ViewDict = JSON.parse(input);
    console.log(viewSelector.match(viewDict));
    rl.close();
});
