```typescript
import * as readline from 'readline';

// 信頼できるベンジンドメイン
const benignDomains = ['microsoft.com', 'w3.org', 'cdn.jsdelivr.net', 'cdnjs.cloudflare.com'];

// 知られているベンダーのドメイン
const lowRiskDomains = ['github.com', 'npmjs.com', 'cloudflare.com'];

// 未知のドメインを検出するための単純なパターン
const unknownDomainPattern = /^(?!.*\.(com|org|net|io|gov|edu|co|cc|me|tech|xyz))[\w-]+\.[\w.-]{2,}$/;

// タイポスクワッティングやダイナミックドメインを示すパターン
const highRiskPatterns = [
  /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/, // IPアドレス
  /xn--[a-z0-9]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/, // IDNドメイン
  /(\.co[0-9])|(\.g00gle)|(\.g00glemail)/ // タイポスクワッティングの例
];

// URLをリスクレベルに基づいて分類
function categorizeURL(url: string): string {
  const urlObj = new URL(url);
  const hostname = urlObj.hostname.toLowerCase();
  const domain = hostname.split('.').slice(-2).join('.');

  // ベンジンドメインを確認
  if (benignDomains.includes(domain)) {
    return 'benign';
  }

  // 信頼できるベンダードメインを確認
  if (lowRiskDomains.includes(domain)) {
    return 'low';
  }

  // 未知のドメインを確認
  if (unknownDomainPattern.test(domain)) {
    return 'medium';
  }

  // 高リスクパターンを確認
  for (const pattern of highRiskPatterns) {
    if (pattern.test(url)) {
      return 'high';
    }
  }

  // 未分類のURLのデフォルト
  return 'medium';
}

