```typescript
import * as readline from 'readline';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

const benignDomains = ['microsoft.com', 'w3.org', 'cdn.jsdelivr.net', 'cdnjs.cloudflare.com'];
const lowRiskDomains = ['github.com', 'npmjs.com'];
const ipPattern = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
const typoPattern = /([a-z0-9-]+\.)+[a-z]{2,}/i;

function categorizeURL(url: string): string {
  try {
    const urlObj = new URL(url);
    const domain = urlObj.hostname;

    if (benignDomains.includes(domain)) {
      return 'benign';
    }

    if (lowRiskDomains.includes(domain)) {
      return 'low';
    }

    if (ipPattern.test(domain)) {
      return 'high';
    }

    if (typoPattern.test(domain) && !domain.includes('.')) {
      return 'high';
    }

    return 'medium';
  } catch {
    return 'unknown';
  }
}

rl.on('line', (input: string) => {
  const trimmedInput = input.trim();
  if (trimmedInput) {
    console.log(categorizeURL(trimmedInput));
  }
});
```

