        String input = scanner.nextLine();
        scanner.close();

        Object result = decode(input);
        System.out.println(Arrays.toString((Object[]) result));
    }

    public static Object decode(String input) {
        // Check if input is a tuple
        if (input.startsWith("(") && input.endsWith(")")) {
            // Remove the outer parentheses
            input = input.substring(1, input.length() - 1);

            // Split by the inner tuple structure
            int firstCommaIndex = input.indexOf(',');
            int secondCommaIndex = input.indexOf(',', firstCommaIndex + 1);
            int closingParenIndex = input.indexOf(')', secondCommaIndex);

            String modelPart = input.substring(0, firstCommaIndex).trim();
            String indicesPart = input.substring(secondCommaIndex + 1, closingParenIndex).trim();

            // Parse the ParaxialModel
            ParaxialModel model = parseParaxialModel(modelPart);

            // Parse the indices
            int[] indices = Arrays.stream(indicesPart.replaceAll("[()]", "").split(","))
                                  .mapToInt(Integer::parseInt)
                                  .toArray();

            return new Object[]{model, indices[0], indices[1]};
        } else {
            // Directly parse as ParaxialModel if not a tuple
            return new Object[]{parseParaxialModel(input), 1, -1};
        }
    }

    private static ParaxialModel parseParaxialModel(String modelString) {
        // Assuming modelString is in format "ParaxialModel{modelData='ModelData'}"
        String modelData = modelString.replaceAll("[^']+", "");
        return new ParaxialModel(modelData);
    }
}
