        // 入力がタプルの場合は解釈し、ParaxialModelとインデックスを返す
        // ここでは単純化のため、入力が整数の場合はParaxialModelとして扱う
        try {
            int value = Integer.parseInt(input);
            ParaxialModel model = new ParaxialModel();
            return new Object[]{model, value};
