            String[] parts = input.replaceAll("[()]", "").split(",");
            ParaxialModel model = new ParaxialModel(); // 実際の解釈に応じて変更
            int bgn = Integer.parseInt(parts[1].trim());
            int end = Integer.parseInt(parts[2].trim());
            return new Object[]{model, new Object[]{bgn, end}};
        }
    }

    private static Object[] decodeLens(Object lensPackage) {
        if (lensPackage instanceof Object[]) {
            Object[] packageArray = (Object[]) lensPackage;
            ParaxialModel paraxModel = (ParaxialModel) packageArray[0];
            Object[] indices = (Object[]) packageArray[1];
            int bgn = (int) indices[0];
            int end = (int) indices[1];
            return new Object[]{paraxModel, bgn, end};
