import java.util.Scanner;

public class IntegerSequenceConverter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            // Read n from input
            int n = Integer.parseInt(scanner.nextLine());

            // Read value from input
            String[] values = scanner.nextLine().split(" ");

            // Convert values to integers
            int[] intValues = new int[values.length];
            for (int i = 0; i < values.length; i++) {
                intValues[i] = Integer.parseInt(values[i]);
            }

            // Validate and generate the output sequence
            if (values.length == 1) {
                // Single integer, duplicate it n times
                if (intValues[0] <= 0) throw new IllegalArgumentException("Value must be positive");
                System.out.print("[");
                for (int i = 0; i < n; i++) {
                    System.out.print(intValues[0]);
                    if (i < n - 1) System.out.print(", ");
                }
                System.out.println("]");
            } else if (values.length == n) {
                // Array of integers, check for positivity
                boolean allPositive = true;
                for (int val : intValues) {
                    if (val <= 0) {
                        allPositive = false;
                        break;
                    }
                }
                if (!allPositive) throw new IllegalArgumentException("All values must be positive");
                System.out.print("[");
                for (int i = 0; i < n; i++) {
