    for (int i = 1; i < n; ++i) {
        // 現在の行のコピーを作成
        std::vector<char> previousLine = currentLine;

        for (int j = 0; j < n; ++j) {
            if (j > 0 && j < n - 1) {
                // 隣接する文字が一致するかどうかを確認
                if (previousLine[j - 1] == input[j + 1]) {
                    currentLine[j] = input[j + 1];
                } else if (previousLine[j] == input[j + 1]) {
                    currentLine[j] = previousLine[j - 1];
                } else if (previousLine[j - 1] != previousLine[j]) {
                    currentLine[j] = previousLine[j - 1];
                } else {
                    currentLine[j] = previousLine[j] ^ 1; // ビット反転
                }
            } else if (j > 0) {
                // 境界条件
                currentLine[j] = (previousLine[j - 1] == input[j + 1]) ? input[j + 1] : (previousLine[j - 1] ^ 1);
            } else if (j < n - 1) {
                // 境界条件
                currentLine[j] = (previousLine[j] == input[j + 1]) ? previousLine[j - 1] : input[j + 1];
            } else {
                // 最後の文字
                currentLine[j] = (previousLine[j] == input[j + 1) ? previousLine[j - 1] : (previousLine[j] ^ 1);
            }
        }

        for (char c : currentLine) {
            std::cout << c;
        }
        std::cout << std::endl;
    }
}

int main() {
    std::string input;
    std::getline(std::cin, input);
    generateOutputLines(input);
    return 0;
}
