// ヘルパーにはstd::stringをJSON文字列に変換する関数を定義
std::string to_json_string(const std::string& str) {
    std::string result = "\"";
    for (char c : str) {
        switch (c) {
            case '\\': result += "\\\\""; break;
            case '"': result += "\\\""; break;
            case '\b': result += "\\b"; break;
            case '\f': result += "\\f"; break;
            case '\n': result += "\\n"; break;
