        return "{\"type\": \"bigint\", \"value\": \"" + std::to_string(static_cast<long long long>(d)) + "\"}";
    }
    return "{\"type\": \"number\", \"value\": " + std::to_string(static_cast<long long>(d)) + "}";
}

