// JSONオブジェクトを表現するクラス
class Json {
public:
    unordered_map<string, string> data;

    string dump(int indent = 4) const {
        string result = "{\n";
        for (auto it = data.begin(); it != data.end(); ++it) {
            if (it != data.begin()) {
                result += string(indent, ' ') + ",";
            }
            result += string(indent, ' ') + "\"" + it->first + "\": \"" + it->second + "\"";
        }
        result += "\n}";
        return result;
    }
};

int main() {
    string line;
    unordered_map<string, string> data;

    // 入力全体を読み取る
    string input;
    while (getline(cin, line)) {
        input += line + "\n";
    }

    // 入力をストリームとして扱う
