// ブロックのデータを確認する関数
bool isCumulativeStateMissing(const CacheList& cache_list) {
    // top-level entries を確認
    bool has_skip = false;
    bool has_cumulative = false;
    for (const auto& entry : cache_list.entries) {
        if (entry == "skip") {
            has_skip = true;
        }
        if (entry == "cumulative") {
            has_cumulative = true;
        }
    }
    if (has_skip && !has_cumulative) {
        return true;
    }

    // sub-slices を再帰的に確認
    for (const auto& sub_slice : cache_list.sub_slices) {
        if (isCumulativeStateMissing(sub_slice)) {
            return true;
        }
    }

    return false;
}

// 標準入力からCacheListを構築する関数
