    std::string line;
    while (std::getline(input, line) && !line.empty()) {
        if (line == "sub_slice:") {
            cache_list.sub_slices.push_back(parseCacheList(input));
        } else {
            cache_list.entries.push_back(line);
        }
    }
    return cache_list;
}

