std::vector<int> parseInput(const std::string& input) {
    std::vector<int> result;
    std::istringstream iss(input);
    std::string token;
    while (std::getline(iss, token, ',')) {
        token.erase(0, token.find_first_not_of(" \t\n\r\f\v")); // Trim leading whitespace
        token.erase(token.find_last_not_of(" \t\n\r\f\v") + 1); // Trim trailing whitespace
        if (isInteger(token)) {
            result.push_back(std::stoi(token));
        } else {
            throw std::invalid_argument("Invalid input: All elements must be integers.");
        }
    }
    return result;
}

int main() {
