    while (std::getline(std::cin, line)) {
        try {
            std::vector<int> numbers = parseInput(line);
            std::cout << "[";
            for (size_t i = 0; i < numbers.size(); ++i) {
                std::cout << numbers[i];
                if (i < numbers.size() - 1) {
                    std::cout << ", ";
                }
            }
            std::cout << "]" << std::endl;
        } catch (const std::invalid_argument& e) {
            std::cerr << "{\"error\": \"" << e.what() << "\"}" << std::endl;
        }
    }
    return 0;
}
