using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        // 標準入力から最大サンプル数を読み取る
        int maxSamples = int.Parse(Console.ReadLine());

        // 標準入力から値のリストを読み取る
        List<float> values = new List<float>();
        string line;
        while ((line = Console.ReadLine()) != null && !string.IsNullOrWhiteSpace(line))
        {
            values.Add(float.Parse(line));
        }

        // 結果を格納するリスト
        List<float> result = SampleValues(values, maxSamples);

        // 結果を標準出力に書き出す
        Console.WriteLine(string.Join(" ", result));
    }

    static List<float> SampleValues(List<float> values, int maxSamples)
    {
        int n = values.Count;

        // valuesの長さがmax_samples以下の場合は全てを返す
        if (n <= maxSamples)
        {
            return values;
        }

        // 均等に間隔を空けたインデックスを計算
        List<float> sampledValues = new List<float>();
        double step = (n - 1) / (maxSamples - 1);

        for (int i = 0; i < maxSamples; i++)
        {
            int index = (int)Math.Round(step * i);
            sampledValues.Add(values[index]);
        }

        return sampledValues;
    }
}
```

この修正では、値を1行ずつ読み取るようにし、各行を`float`に変換してリストに追加しています。これにより、入力が期待通りに処理され、正しくサンプリングされた結果が出力されます。

### 実装方針
`sample_evenly`関数を実装し、`values`リストから最大`max_samples`値を均等にサンプリングする。`max_samples`が`values`の長さ以下の場合は、リスト全体を返す。それ以上の場合は、均等に間隔を空けたインデックスを使用してサンプリングを行い、バイアスを避ける。

### 実装

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class EvenSampler
{
    public static List<float> SampleEvenly(List<float> values, int maxSamples)
    {
        int n = values.Count;
        if (n <= maxSamples)
        {
            return values.ConvertAll(v => (float)v);
        }

        List<float> sampledValues = new List<float>();
        double step = (n - 1) / (maxSamples - 1);

        for (int i = 0; i < maxSamples; i++)
        {
            int index = (int)Math.Floor(i * step);
            sampledValues.Add(values[index]);
        }

        return sampledValues;
    }

    public static void Main()
    {
        // Example usage:
        List<float> values = new List<float> { 1f, 2f, 3f };
        int maxSamples = 1;
        List<float> result = SampleEvenly(values, maxSamples);

        foreach (var value in result)
        {
            Console.WriteLine(value);
        }
    }
}
```

### 説明
- **入力チェック**: `values`の長さが`maxSamples`以下の場合、`values`をそのまま返す。
- **ステップ計算**: `values`の長さから`maxSamples`を引いた値を`maxSamples - 1`で割ってステップを計算。
- **サンプリング実行**: 計算したステップを使って`values`から均等にインデックスを取得し、対応する値をリストに追加。
- **出力**: サンプリングされたリストを出力。

C#プログラムが失敗した理由は、入力値の妥当性チェックが不十分で、特に`output_indices`の各要素が`chunk_size`より大きい場合に適切に処理されていないためです。この問題を修正するために、`output_indices`の各要素が`chunk_size`より大きいかどうかを確認し、不正な場合は`ValueError`を送出します。

以下は修正したコードです：

```csharp
using System;
using System.Linq;

class Program
{
    static void Main()
    {
        // 標準入力からoutput_indicesを読み取る
        var outputIndicesInput = Console.ReadLine();
        var outputIndices = outputIndicesInput.Split(' ').Select(int.Parse).ToArray();

        // 標準入力からchunk_sizeを読み取る
        int chunkSize = int.Parse(Console.ReadLine());

        // 妥当性チェック
        if (chunkSize <= 0)
        {
            throw new ArgumentException("chunk_size must be a positive integer.");
        }

        // output_indicesの各要素がchunk_sizeより大きいかどうかを確認
        if (outputIndices.Any(index => index >= chunkSize))
        {
            throw new ValueError("output_indices must contain values less than chunk_size.");
        }

        // 結果を格納する配列
        int[] sendDestChips = new int[outputIndices.Length];
        int[] sendLocalRows = new int[outputIndices.Length];

        // 各output_indexに対して計算
        for (int i = 0; i < outputIndices.Length; i++)
        {
            int globalIndex = outputIndices[i];
            sendDestChips[i] = globalIndex / chunkSize;
            sendLocalRows[i] = globalIndex % chunkSize;
        }

        // 結果を標準出力に書き出す
        Console.WriteLine(string.Join(" ", sendDestChips));
        Console.WriteLine(string.Join(" ", sendLocalRows));
    }
}

// ValueErrorクラスの定義
public class ValueError : Exception
{
    public ValueError(string message) : base(message) { }
}
```

この修正では、`output_indices`の各要素が`chunk_size`より大きいかどうかを確認し、不正な場合はカスタムの`ValueError`を送出しています。また、`ValueError`クラスを定義して、例外を送出するための基盤を提供しています。

### 実装方針

標準入力から1行ずつ読み取り、各行を整数のリストとして解析し、`compute_send_routing`関数を使用して結果を計算します。その後、結果を出力します。入力の妥当性を確認し、不正な場合は`ValueError`を送出します。

### C# コード

```csharp
using System;
using System.Linq;

class Program
{
    static void Main()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            try
            {
                var outputIndices = line.Split(' ').Select(int.Parse).ToArray();
                var chunkSize = int.Parse(Console.ReadLine());

                var (sendDestChips, sendLocalRows) = ComputeSendRouting(outputIndices, chunkSize);

                Console.WriteLine($"[{string.Join(", ", sendDestChips.Select(i => i.ToString())}], [{string.Join(", ", sendLocalRows.Select(i => i.ToString())}]");
            }
            catch (FormatException)
            {
                throw new ArgumentException("Invalid input format. Please ensure all inputs are integers.");
            }
        }
    }

    static (int[], int[]) ComputeSendRouting(int[] outputIndices, int chunkSize)
    {
        if (chunkSize <= 0)
            throw new ArgumentException("chunkSize must be greater than zero.");

        var sendDestChips = outputIndices.Select(i => i / chunkSize).ToArray();
        var sendLocalRows = outputIndices.Select(i => i % chunkSize).ToArray();

        return (sendDestChips, sendLocalRows);
    }
}
```

### 説明

- **入力処理**: 標準入力から1行ずつ読み取り、各行を整数の配列に変換します。
- **計算**: `ComputeSendRouting`関数を使用して、`send_dest_chips`と`send_local_rows`を計算します。
- **出力**: 結果を指定された形式で標準出力に書き出します。
- **エラーハンドリング**: 入力の妥当性を確認し、不正な場合は`ArgumentException`を送出します。

### 失敗の原因

現在のコードでは、`broker_order_id`や`client_order_id`が`None`（C#では`null`）の場合に対する妥当性チェックが欠けています。これにより、`None`や`null`が入力された場合に`ValueError`を送出する仕様に沿っていません。

### 修正したコード

以下は、入力値の妥当性チェックを追加し、`None`や`null`が入力された場合に`ValueError`を送出するように修正したコードです。

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class OrderSubmitter
{
    private Dictionary<string, string> _brokerToClientOrderIds = new Dictionary<string, string>();
    private Dictionary<string, string> _clientToBrokerOrderIds = new Dictionary<string, string>();
    private HashSet<string> _closedBrokerOrderIds = new HashSet<string>();
    private const int _CLOSED_ORDER_ID_LIMIT = 100; // 例として100を設定

    public void ProcessInput()
    {
        string input;
        while ((input = Console.ReadLine()) != null)
        {
            var parts = input.Split(',');
            if (parts.Length != 3) continue;

            string brokerOrderId = parts[0].Trim();
            string clientId = parts[1].Trim();
            string orderStatus = parts[2].Trim();

            // 入力値の妥当性チェック
            if (string.IsNullOrEmpty(brokerOrderId) || string.IsNullOrEmpty(clientId))
            {
                throw new ArgumentException("Broker Order ID and Client Order ID cannot be null or empty.");
            }

            if (orderStatus == "submitted")
            {
                _syncOrderIDMapping(brokerOrderId, clientId);
            }
            else if (orderStatus == "closed")
            {
                _closeOrderMapping(brokerOrderId);
                _closedBrokerOrderIds.Add(brokerOrderId);
                if (_closedBrokerOrderIds.Count > _CLOSED_ORDER_ID_LIMIT)
                {
                    _closedBrokerOrderIds.Remove(_closedBrokerOrderIds.Min());
                }
            }

            bool isKnownOrder = IsKnownOrder(brokerOrderId);
            Console.WriteLine(isKnownOrder ? "Known Order" : "Unknown Order");
        }
    }

    private void _syncOrderIDMapping(string brokerOrderId, string clientId)
    {
        _brokerToClientOrderIds[brokerOrderId] = clientId;
        _clientToBrokerOrderIds[clientId] = brokerOrderId;
    }

    private void _closeOrderMapping(string brokerOrderId)
    {
        if (_brokerToClientOrderIds.ContainsKey(brokerOrderId))
        {
            _brokerToClientOrderIds.Remove(brokerOrderId);
        }

        if (_clientToBrokerOrderIds.ContainsValue(brokerOrderId))
        {
            var clientId = _clientToBrokerOrderIds.First(x => x.Value == brokerOrderId).Key;
            _clientToBrokerOrderIds.Remove(clientId);
        }
    }

    private bool IsKnownOrder(string brokerOrderId)
    {
        if (_brokerToClientOrderIds.ContainsKey(brokerOrderId))
        {
            return true;
        }
        return _closedBrokerOrderIds.Contains(brokerOrderId);
    }
}

class Program
{
    static void Main()
    {
        var orderSubmitter = new OrderSubmitter();
        orderSubmitter.ProcessInput();
    }
}
```

この修正では、`brokerOrderId`や`clientId`が`null`または空文字列の場合に`ArgumentException`を送出するようにしました。また、`_syncOrderIDMapping`メソッドで`brokerOrderId`と`clientId`の双方向のマッピングを行うように修正しました。

To implement the specified functionality in C#, we need to create a method that checks if a given broker or client order ID is known within the current session. The method should validate the input values and raise a `ValueError` if they are invalid. Additionally, it should read standard input values one by one, outputting only the result.

Here's how we can implement this in C#:

```csharp
using System;
using System.Collections.Generic;

public class OrderChecker
{
    private Dictionary<string, string> _brokerToClientOrderIds = new Dictionary<string, string>();
    private Dictionary<string, string> _clientToBrokerOrderIds = new Dictionary<string, string>();
    private HashSet<string> _closedBrokerOrderIds = new HashSet<string>();
    private const int _CLOSED_ORDER_ID_LIMIT = 100; // Example limit

    public bool IsKnownBrokerOrder(string brokerOrderId, string clientOrderId)
    {
        ValidateInput(brokerOrderId, clientOrderId);

        if (!string.IsNullOrEmpty(brokerOrderId) && _brokerToClientOrderIds.ContainsKey(brokerOrderId))
        {
            return true;
        }
        if (!string.IsNullOrEmpty(clientOrderId) && _clientToBrokerOrderIds.ContainsKey(clientOrderId))
        {
            return true;
        }
        if (!string.IsNullOrEmpty(brokerOrderId) && _closedBrokerOrderIds.Contains(brokerOrderId))
        {
            return true;
        }
        return false;
    }

    private void ValidateInput(string brokerOrderId, string clientOrderId)
    {
        if (brokerOrderId != null && brokerOrderId.Length > 20)
        {
            throw new ArgumentException("Broker order ID is too long.");
        }
        if (clientOrderId != null && clientOrderId.Length > 20)
        {
            throw new ArgumentException("Client order ID is too long.");
        }
    }

    public static void Main()
    {
        var checker = new OrderChecker();
        var brokerOrderIds = new List<string> { "order1", "order2", "order3" };
        var clientOrderIds = new List<string> { "client1", "client2", "client3" };

        foreach (var brokerOrderId in brokerOrderIds)
        {
            foreach (var clientOrderId in clientOrderIds)
            {
                bool result = checker.IsKnownBrokerOrder(brokerOrderId, clientOrderId);
                Console.WriteLine(result);
            }
        }
    }
}
```

### Explanation:

- **Data Structures**: We use dictionaries to map broker to client IDs and vice versa, and a set to track closed broker order IDs.
- **Input Validation**: The `ValidateInput` method checks if the IDs are not null and within a reasonable length, throwing an `ArgumentException` if they are invalid.
- **Main Logic**: The `IsKnownBrokerOrder` method checks if the given IDs are present in any of the mappings or the closed set.
- **Main Method**: Simulates reading from standard input by iterating over predefined lists of order IDs and outputs the result for each combination.

This implementation adheres to the requirement of using only standard libraries and avoids unnecessary output.

