// RetryableError は一時的な例外を表すためのインタラクトです.
type RetryableError interface {
	error
	IsRetryable() bool
}

// CustomError はRetryableErrorインタラクトを実装するカスタムエラーです.
type CustomError struct {
	Module  string
	Name    string
	Err     error
}

func (e *CustomError) Error() string {
	return e.Err.Error()
}

func (e *CustomError) IsRetryable() bool {
	if e.Module == "httpx" {
		return false
	}
	retryableErrors := map[string]bool{
		"ConnectError":     true,
		"ReadError":        true,
		"WriteError":       true,
		"TimeoutException": true,
		"NetworkError":     true,
		"RateLimitError":   true,
		"InternalServerError": true,
		"APITimeoutError":  true,
		"APIConnectionError": true,
	}
	return retryableErrors[e.Name]
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		input := strings.TrimSpace(scanner.Text())

		// 入力が特定の例外名の場合、それに基づいてCustomErrorを作成
		var module string
		var err error
		switch input {
		case "TimeoutError":
			module = "builtins"
			err = errors.New("TimeoutError")
		case "ConnectionError":
			module = "builtins"
			err = errors.New("ConnectionError")
		default:
			module = "httpx"
			err = errors.New(input)
		}

		customErr := &CustomError{
			Module: module,
			Name:   err.Error(),
			Err:    err,
		}

		// エラーが一時的に見えるかどうかを確認します.
		if customErr.IsRetryable() {
			fmt.Println("True") // 一時的なエラーの場合はTrueを出力
		} else {
			fmt.Println("False") // 一時的でないエラーの場合はFalseを出力
		}
	}
}
