// powerMod は,base^exp mod modulusを計算します.
func powerMod(base, exp, modulus int64) int64 {
	result := int64(1)
	base = base % modulus
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % modulus
		}
		exp = exp >> 1
		base = (base * base) % modulus
	}
	return result
}

// findOrder は,modulus群内のelementの順序を決定します.
func findOrder(element, modulus int64, phiMDecomp []int64) int64 {
	phiM := phiMDecomp[0]
	for _, divisor := range phiMDecomp {
		if powerMod(element, phiM/divisor, modulus) == 1 {
			phiM = divisor
		}
	}
	return phiM
}

