この問題を解決するには、整数 `element` を `modulus` で割った余りの順序を計算する必要があります。この順序は、`element`の最小の正の整数 `k` で、`element^k ≡ 1 (mod modulus)` が成り立つようなものです。

実装方針として、`element`が`modulus`の約数でないことを確認し、`element`が`modulus`と互いに素であることを確認します。その後、`phi_m`（`modulus`のオイラーのトーシェント関数）の約数分解を使用して、`element`の順序を効率的に計算します。

以下にGoでの実装を示します：

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// gcd は2つの数の最大公約数を計算します。
func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

// orderOfElement は、modulusでのelementの順序を計算します。
func orderOfElement(element, modulus, phiM int, phiMDecomposition map[int]int) int {
	if gcd(element, modulus) != 1 {
		return 0
	}

	order := phiM
	for factor, count := range phiMDecomposition {
		for i := 0; i < count; i++ {
			temp := phiM / factor
			if powMod(element, temp, modulus) == 1 {
				order = temp
			} else {
				phiM = temp
			}
		}
	}
	return order
}

// powMod は、base^exponent mod modulusを計算します。
func powMod(base, exponent, modulus int) int {
	result := 1
	base = base % modulus
	for exponent > 0 {
		if exponent%2 == 1 {
			result = (result * base) % modulus
		}
		exponent = exponent >> 1
		base = (base * base) % modulus
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	inputs := strings.Fields(scanner.Text())

	element, _ := strconv.Atoi(inputs[0])
	modulus, _ := strconv.Atoi(inputs[1])
	phiM, _ := strconv.Atoi(inputs[2])

	// phiM_decompositionを計算します。
	phiMDecomposition := make(map[int]int)
	phiMcopy := phiM
	for i := 2; i*i <= phiMcopy; i++ {
		for phiMcopy%i == 0 {
			phiMDecomposition[i]++
			phiMcopy /= i
		}
	}
	if phiMcopy > 1 {
		phiMDecomposition[phiMcopy]++
	}

	// elementの順序を計算して出力します。
	order := orderOfElement(element, modulus, phiM, phiMDecomposition)
	fmt.Println(order)
}
```

