現在のコードは、`part_index`が`num_parts - 2`の場合に`end_range`を空文字列にするようにしていますが、これはPythonの元の仕様にはありません。また、`part_index`が`num_parts - 1`の場合にのみ`total_size`を考慮するように修正する必要があります。さらに、プロンプト文や余計な出力を削除する必要があります。

以下が修正したコードです：

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func calculateRangeParameter(partSize int, partIndex int, numParts int, totalSize *int) string {
	start := partIndex * partSize
	end := start + partSize - 1

	if partIndex == numParts-1 && totalSize != nil {
		end = *totalSize - 1
	}

	return fmt.Sprintf("bytes=%d-%d", start, end)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	partSizeStr, _ := reader.ReadString('\n')
	partSizeStr = strings.TrimSpace(partSizeStr)
	partSize, err := strconv.Atoi(partSizeStr)
	if err != nil {
		return
	}

	partIndexStr, _ := reader.ReadString('\n')
	partIndexStr = strings.TrimSpace(partIndexStr)
	partIndex, err := strconv.Atoi(partIndexStr)
	if err != nil {
		return
	}

	numPartsStr, _ := reader.ReadString('\n')
	numPartsStr = strings.TrimSpace(numPartsStr)
	numParts, err := strconv.Atoi(numPartsStr)
	if err != nil {
		return
	}

	totalSizeStr, _ := reader.ReadString('\n')
	totalSizeStr = strings.TrimSpace(totalSizeStr)
	var totalSize *int
	if totalSizeStr != "" {
		totalSizeInt, err := strconv.Atoi(totalSizeStr)
		if err != nil {
			return
		}
		totalSize = &totalSizeInt
	}

	result := calculateRangeParameter(partSize, partIndex, numParts, totalSize)
	fmt.Println(result)
}
```

この修正により、プロンプト文や余計な出力が削除され、`part_index`が`num_parts - 1`の場合にのみ`total_size`を考慮するようになりました。

`calculate_range_parameter`関数のバグを修正するためには、最後のパーティーの`end_range`の計算方法を調整する必要があります。現在の実装では、`end_range`が空文字列に設定されていますが、`total_size`が指定されている場合は`total_size - 1`に設定されます。しかし、`end_range`が空文字列のままになると、`range_param`の形式が正しくなくなってしまいます。

修正するには、`end_range`が空文字列の場合には、`end_range`を`start_range + part_size - 1`に設定するようにします。これにより、最後のパーティーの範囲が正しく計算されます。

以下に修正後のコードを示します：

```go
package main

import (
	"fmt"
)

func calculate_range_parameter(part_size, part_index, num_parts int, total_size *int) string {
	start_range := part_index * part_size
	var end_range string
	if part_index == num_parts-1 {
		if total_size != nil {
			end_range = fmt.Sprintf("%d", (*total_size)-1)
		}
	} else {
		end_range = fmt.Sprintf("%d", start_range+part_size-1)
	}
	if end_range == "" {
		end_range = fmt.Sprintf("%d", start_range+part_size-1)
	}
	range_param := fmt.Sprintf("bytes=%d-%s", start_range, end_range)
	return range_param
}

func main() {
	var part_size, part_index, num_parts int
	var total_size *int

	// 標準入力から値を読み取る
	fmt.Scan(&part_size)
	fmt.Scan(&part_index)
	fmt.Scan(&num_parts)
	if total_sizePtr := new(int); fmt.Scan(total_sizePtr) == 1 {
		total_size = total_sizePtr
	}

	// 範囲パラメータを計算して出力
	fmt.Println(calculate_range_parameter(part_size, part_index, num_parts, total_size))
}
```

このコードは、標準入力から`part_size`、`part_index`、`num_parts`、およびオプションの`total_size`を読み取り、`calculate_range_parameter`関数を使って範囲パラメータを計算し、結果を標準出力に出力します。

