fn expected_cache_layer_count(model: &Model, hybrid_num_layers: Option<usize>) -> Option<usize> {
    if let Some(hybrid_num_layers) = hybrid_num_layers {
        return Some(hybrid_num_layers);
    }
    if let Some(cache) = model.make_cache() {
        if !cache.is_empty() {
            return Some(cache.len());
        }
    }
    for attr in vec!["args", "config"] {
        if let Some(cfg) = model.get_attr(attr) {
            if let Some(num_layers) = cfg.num_hidden_layers {
                return Some(num_layers);
            }
        }
    }
    None
}

struct Model {
    // 仮の属性とメソッド
    args: Option<ModelConfig>,
    config: Option<ModelConfig>,
}

impl Model {
    fn make_cache(&self) -> Option<Vec<u8>> {
        // 仮のキャッシュ作成ロジック
        Some(vec![0; 5]) // 例として5つのキャッシュエントリを返す
    }

    fn get_attr<T>(&self, attr: &str) -> Option<T>
    where
        T: std::marker::Sized,
    {
        match attr {
            "args" => self.args.as_ref().map(|x| x as &dyn std::any::Any),
            "config" => self.config.as_ref().map(|x| x as &dyn std::any::Any),
            _ => None,
        }
        .and_then(|any| any.downcast_ref::<T>())
    }
}

struct ModelConfig {
