}

fn main() {
    let stdin = io::stdin();
    let reader = stdin.lock();

    for line in reader.lines() {
        let line = line.expect("Failed to read line");
        let parts: Vec<&str> = line.split(',').collect();
        let model = Model {
            args: Some(ModelConfig {
                num_hidden_layers: parts.get(1).and_then(|s| s.parse().ok()),
            }),
            config: Some(ModelConfig {
                num_hidden_layers: parts.get(2).and_then(|s| s.parse().ok()),
            }),
