```rust
use std::collections::HashMap;
use std::io::{self, BufRead};
use std::env;

/// Parses the ninth column of a GFF3 or GTF record.
///
/// Handles both `key=value` (GFF3) and `key value` (GTF) conventions.
/// Handles quoted values (e.g., `key="value"`) and values containing semicolons (e.g., `MF="GO:0005524;GO:0004004"`) correctly.
/// URL-encoded characters (`%09`, `%0A`, etc.) are decoded before parsing.
///
/// # Arguments
/// * `text` - Raw attributes string from column 9 of a GFF3 line.
/// # Returns
/// * `HashMap` mapping attribute names to their (unquoted) values.
fn parse_attributes(text: &str) -> HashMap<String, String> {
    let mut attributes = HashMap::new();
    let mut lines = text.lines();

    while let Some(line) = lines.next() {
        let parts: Vec<_> = line.splitn(2, '=').collect();
        let (key, value) = if parts.len() == 2 {
            (parts[0].trim(), parts[1])
        } else if let Some((key, value)) = parts.into_iter().next() {
            (key.trim(), value.trim())
        } else {
            continue;
        };

        // Handle URL-encoded characters
        let mut value = url_decode(value);

        // Handle quoted values
        if value.starts_with('"') && value.ends_with('"') {
            value = &value[1..value.len() - 1];
        }

        // Handle semicolons in the value
        let values: Vec<&str> = value.split(';').map(str::trim).collect();
        for val in values {
            if !val.is_empty() {
                attributes.insert(key.to_string(), val.to_string());
            }
        }
    }

    attributes
}

/// Decodes URL-encoded characters in a string.
fn url_decode(input: &str) -> String {
    let mut output = String::new();
    let mut chars = input.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '%' {
            if let (Some(next1), Some(next2)) = (chars.peek(), chars.peek().map(|c| chars.clone().nth(1))) {
                if let (Some(next1), Some(next2)) = (next1, next2) {
                    if let Ok(code) = u8::from_str_radix(&format!("{}{}", next1, next2), 16) {
                        output.push(std::char::from_u32(code as u32).unwrap());
                        chars.next(); // consume next1
                        chars.next(); // consume next2
                    } else {
                        output.push(ch);
                    }
                } else {
                    output.push(ch);
                }
            } else {
                output.push(ch);
            }
        } else {
            output.push(ch);
        }
    }

    output
}

fn main() {
    let stdin = io::stdin();
    let mut input = String::new();
    stdin.lock().read_to_string(&mut input).expect("Failed to read from stdin");

    let attributes = parse_attributes(&input);
    for (key, value) in attributes {
        println!("{}: {}", key, value);
    }
}
