            } else {
                let (key, value, expected_type) = (parts[0], parts[1], parts[2]);
                if !key.starts_with("key_") {
                    errors.push("キーは'key_'で始まるべきです.".to_string());
                }
                if !value.chars().all(|c| c.is_alphanumeric() || "+-".contains(c)) {
