use std::collections::HashMap;
use std::io::{self, BufRead};

// タプルのシーケンスまたは辞書からキーと値のペアを反復するヘルパー関数
fn _items<I, K, V>(items: I) -> impl Iterator<Item = (K, V)>
where
    I: IntoIterator<Item = (K, V)>,
    K: Clone,
    V: Clone,
{
    items.into_iter()
}

fn main() {
    // 標準入力を読み取る
    let stdin = io::stdin();
    let input_lines = stdin.lock().lines().map(Result::unwrap).collect::<Vec<_>>();

    // 入力を処理して辞書を作成
    let mut map: HashMap<i32, i32> = HashMap::new();
    for line in input_lines {
        let nums: Vec<i32> = line
            .split_whitespace()
            .filter_map(|s| s.parse::<i32>().ok())
            .collect();

        if nums.len() == 2 {
            map.insert(nums[0], nums[1]);
        }
    }

    // 辞書を反復して結果を出力
    for (k, v) in _items(map) {
        println!("{}", v);
    }
}
```

